from abc import ABC, abstractmethod


class HotDrinkMaker(ABC):
    # Template method - sequence is fixed
    def make(self):
        self.boil_water()       # shared
        self.add_ingredient()   # subclass fills in
        self.pour_in_cup()      # shared
        self.add_extras()       # subclass fills in

    def boil_water(self):
        print("Boiling water")

    @abstractmethod
    def add_ingredient(self):
        pass

    def pour_in_cup(self):
        print("Pouring into cup")

    @abstractmethod
    def add_extras(self):
        pass


class TeaMaker(HotDrinkMaker):
    def add_ingredient(self):
        print("Steeping tea leaves")

    def add_extras(self):
        print("Adding lemon")


if __name__ == "__main__":
    tea = TeaMaker()
    tea.make()

