    public final void make() {
        boilWater();       // shared
        addIngredient();   // subclass fills in
        pourInCup();       // shared
        addExtras();       // subclass fills in
    }

    protected void boilWater() { System.out.println("Boiling water"); }

    protected abstract void addIngredient();

    protected void pourInCup() { System.out.println("Pouring into cup"); }

    protected abstract void addExtras();
}

class TeaMaker extends HotDrinkMaker {
    @Override
    protected void addIngredient() { System.out.println("Steeping tea leaves"); }

    @Override
    protected void addExtras() { System.out.println("Adding lemon"); }
}

public class Main {
    public static void main(String[] args) {
        HotDrinkMaker tea = new TeaMaker();
        tea.make();
    }
}

