#include <bits/stdc++.h>
using namespace std;

class HotDrinkMaker {
public:
    // Template method - sequence is fixed
    void make() {
        boilWater();       // shared
        addIngredient();   // subclass fills in
        pourInCup();       // shared
        addExtras();       // subclass fills in
    }

    virtual ~HotDrinkMaker() = default;

protected:
    virtual void boilWater() { cout << "Boiling water" << endl; }

    virtual void addIngredient() = 0;

    virtual void pourInCup() { cout << "Pouring into cup" << endl; }

    virtual void addExtras() = 0;
};

class TeaMaker : public HotDrinkMaker {
protected:
    void addIngredient() override { cout << "Steeping tea leaves" << endl; }
    void addExtras() override { cout << "Adding lemon" << endl; }
};

int main() {
    TeaMaker tea;
    tea.make();
    return 0;
}

