abstract class OrderProcessor {

    // Template method — fixed sequence, cannot be overridden
    public final void processOrder(String orderId) {
        validateOrder(orderId);
        calculateCost(orderId);
        processPayment(orderId);
        packageItems(orderId);
        shipOrder(orderId);
        addInsurance(orderId);   // Hook — optional override
        sendConfirmation(orderId);
        System.out.println("Order " + orderId + " processing complete.\n");
    }

    // Concrete — shared across all subclasses
    protected void validateOrder(String orderId) {
        System.out.println("[" + orderId + "] Validating order...");
    }

    // Abstract — each subclass MUST implement
    protected abstract void calculateCost(String orderId);

    // Concrete — shared across all subclasses
    protected void processPayment(String orderId) {
        System.out.println("[" + orderId + "] Processing payment...");
    }

    // Concrete — shared across all subclasses
    protected void packageItems(String orderId) {
        System.out.println("[" + orderId + "] Packaging items...");
    }

    // Abstract — each subclass MUST implement
    protected abstract void shipOrder(String orderId);

    // Hook — empty default, subclasses can optionally override
    protected void addInsurance(String orderId) {
        // Default: no insurance. Express and International override this.
    }

    // Concrete — shared across all subclasses
    protected void sendConfirmation(String orderId) {
        System.out.println("[" + orderId + "] Sending confirmation email...");
    }
}

