from abc import ABC, abstractmethod


class OrderProcessor(ABC):

    # Template method - fixed sequence, cannot be overridden
    def process_order(self, order_id):
        self.validate_order(order_id)
        self.calculate_cost(order_id)
        self.process_payment(order_id)
        self.package_items(order_id)
        self.ship_order(order_id)
        self.add_insurance(order_id)  # Hook - optional override
        self.send_confirmation(order_id)
        print(f"Order {order_id} processing complete.\n")

    # Concrete - shared across all subclasses
    def validate_order(self, order_id):
        print(f"[{order_id}] Validating order...")

    # Abstract - each subclass MUST implement
    @abstractmethod
    def calculate_cost(self, order_id):
        pass

    # Concrete - shared across all subclasses
    def process_payment(self, order_id):
        print(f"[{order_id}] Processing payment...")

    # Concrete - shared across all subclasses
    def package_items(self, order_id):
        print(f"[{order_id}] Packaging items...")

    # Abstract - each subclass MUST implement
    @abstractmethod
    def ship_order(self, order_id):
        pass

    # Hook - empty default, subclasses can optionally override
    def add_insurance(self, order_id):
        # Default: no insurance. Express and International override this.
        pass

    # Concrete - shared across all subclasses
    def send_confirmation(self, order_id):
        print(f"[{order_id}] Sending confirmation email...")


class _DemoProcessor(OrderProcessor):
    def calculate_cost(self, order_id):
        print(f"[{order_id}] Calculating cost...")

    def ship_order(self, order_id):
        print(f"[{order_id}] Shipping order...")


if __name__ == "__main__":
    processor = _DemoProcessor()
    processor.process_order("ORD-000")

