#include <bits/stdc++.h>
using namespace std;

class OrderProcessor {
public:
    // Template method - fixed sequence, cannot be overridden
    void processOrder(const string& orderId) {
        validateOrder(orderId);
        calculateCost(orderId);
        processPayment(orderId);
        packageItems(orderId);
        shipOrder(orderId);
        addInsurance(orderId);   // Hook - optional override
        sendConfirmation(orderId);
        cout << "Order " << orderId << " processing complete." << endl << endl;
    }

    virtual ~OrderProcessor() = default;

protected:
