    public final void prepareMeal() {
        gatherIngredients();
        prepareIngredients();
        cook();
        addCondiments();     // Hook — optional
        plate();
        System.out.println("Meal ready!\n");
    }

    // Concrete — shared
    protected void gatherIngredients() {
        System.out.println("Gathering ingredients from storage...");
    }

    // Abstract — subclass MUST implement
    protected abstract void prepareIngredients();

    // Abstract — subclass MUST implement
    protected abstract void cook();

    // Hook — empty default, subclasses can optionally override
    protected void addCondiments() {}

    // Concrete — shared
    protected void plate() {
        System.out.println("Plating the meal...");
    }
}

// Concrete Classes
class VegetarianMeal extends MealPreparer {
    @Override
    protected void prepareIngredients() {
        System.out.println("Vegetarian: chopping vegetables and tofu...");
    }

    @Override
    protected void cook() {
        System.out.println("Vegetarian: stir frying with olive oil...");
    }

    @Override
    protected void addCondiments() {
        System.out.println("Vegetarian: adding herbs and lemon dressing...");
    }
}

class NonVegetarianMeal extends MealPreparer {
    @Override
    protected void prepareIngredients() {
        System.out.println("NonVeg: marinating chicken and prepping sides...");
    }

    @Override
    protected void cook() {
        System.out.println("NonVeg: grilling chicken on high heat...");
    }

    @Override
    protected void addCondiments() {
        System.out.println("NonVeg: adding BBQ sauce and seasoning...");
    }
}

class VeganMeal extends MealPreparer {
    @Override
    protected void prepareIngredients() {
        System.out.println("Vegan: washing lentils, chopping greens...");
    }

    @Override
    protected void cook() {
        System.out.println("Vegan: slow cooking lentil stew...");
    }
    // No condiments — uses default empty hook
}

// Client
