        System.out.println("--- Vegetarian ---");
        veg.prepareMeal();

        System.out.println("--- Non Vegetarian ---");
        nonVeg.prepareMeal();

        System.out.println("--- Vegan ---");
        vegan.prepareMeal();
    }
}

