#include <bits/stdc++.h>
using namespace std;

// Abstract Base Class
class MealPreparer {
public:
    // Template method - fixed sequence
    void prepareMeal() {
        gatherIngredients();
        prepareIngredients();
        cook();
        addCondiments();     // Hook - optional
        plate();
        cout << "Meal ready!" << endl << endl;
    }

    virtual ~MealPreparer() = default;

protected:
    // Concrete - shared
    virtual void gatherIngredients() {
        cout << "Gathering ingredients from storage..." << endl;
    }

    // Abstract - subclass MUST implement
    virtual void prepareIngredients() = 0;

    // Abstract - subclass MUST implement
    virtual void cook() = 0;

    // Hook - empty default, subclasses can optionally override
    virtual void addCondiments() {}

    // Concrete - shared
    virtual void plate() {
        cout << "Plating the meal..." << endl;
    }
};

// Concrete Classes
class VegetarianMeal : public MealPreparer {
protected:
    void prepareIngredients() override {
        cout << "Vegetarian: chopping vegetables and tofu..." << endl;
    }

    void cook() override {
        cout << "Vegetarian: stir frying with olive oil..." << endl;
    }

    void addCondiments() override {
        cout << "Vegetarian: adding herbs and lemon dressing..." << endl;
    }
};

class NonVegetarianMeal : public MealPreparer {
protected:
    void prepareIngredients() override {
        cout << "NonVeg: marinating chicken and prepping sides..." << endl;
    }

    void cook() override {
        cout << "NonVeg: grilling chicken on high heat..." << endl;
    }

    void addCondiments() override {
        cout << "NonVeg: adding BBQ sauce and seasoning..." << endl;
    }
};

class VeganMeal : public MealPreparer {
protected:
    void prepareIngredients() override {
        cout << "Vegan: washing lentils, chopping greens..." << endl;
    }

    void cook() override {
        cout << "Vegan: slow cooking lentil stew..." << endl;
    }
    // No condiments - uses default empty hook
};

// Client
int main() {
    VegetarianMeal veg;
    NonVegetarianMeal nonVeg;
    VeganMeal vegan;

    cout << "--- Vegetarian ---" << endl;
    veg.prepareMeal();

    cout << "--- Non Vegetarian ---" << endl;
    nonVeg.prepareMeal();

    cout << "--- Vegan ---" << endl;
    vegan.prepareMeal();

    return 0;
}
